    private GameSession OrderBoard(bool researched=true)
    {
        var c=CompleteContent();var g=GalaxyGenerator.CreateNewGame(c,new("small",42,10,"harl",CrisesEnabled:false,AmebasEnabled:false,SentriesEnabled:false));var s=g.State!;if(researched)s.Empires[0].KnownTechnologyIds=c.Technologies.Keys.Order(StringComparer.Ordinal).ToList();s.Colonies[0].ProductionReserve=10000;var v=s.Vessels[0];v.RoleId=c.ShipDesigns!.WarshipRoleId;v.Design=new(1);OpenAntares.Simulation.Combat.CombatInitializer.InitializeVessel(c,s,v);OpenAntares.Simulation.Scouting.ScoutInitializer.InitializeVessel(c,10,v);Check(OpenAntares.Simulation.State.GameStateValidator.Validate(c,s).Count==0,"Labelled pre-session order board validates");return new(c,s);
    }
