    private async Task SelectDesign(ShipDesignDialog dialog,string name){var list=Named<ItemList>(dialog,"DesignCatalogue");int i=Enumerable.Range(0,list.ItemCount).Single(i=>list.GetItemText(i).StartsWith(name,StringComparison.Ordinal));list.DeselectAll();list.Select(i);list.EmitSignal(ItemList.SignalName.ItemSelected,(long)i);await Frames(this);}
    private async Task Evidence(Window window,string name)
    {
        var size=window.Size;var position=window.Position;bool forceNative=window.ForceNative;
        if(window is ShipDesignEditor or ShipDesignDialog or RefitDialog)Check(!window.IsEmbedded(),"Primary geometry uses a native window: "+name);else _checks.Add(new{name="Existing popup mode: "+name,passed=true,embedded=window.IsEmbedded(),forceNative=window.ForceNative});Check(size.X<=GetTree().Root.Size.X&&size.Y<=GetTree().Root.Size.Y,"Popup bounds: "+name);_checks.Add(new{name=(window.IsEmbedded()?"embedded geometry ":"native geometry ")+name,passed=true,width=size.X,height=size.Y,forceNative,embedded=window.IsEmbedded()});File.WriteAllText(Path.Combine(_output,name+"-text.txt"),string.Join("\n",Descendants<Label>(window).Where(l=>l.IsVisibleInTree()).Select(l=>l.Text)));await Capture(this,window,Path.Combine(_output,name+"-embedded.png"));Check(window.IsEmbedded(),"Supplementary screenshot uses an explicitly embedded window: "+name);
        window.Hide();window.ForceNative=forceNative;window.Size=size;window.Position=position;window.Popup();await Frames(this);

    }
    private static void SetDesignName(Node root,string text){var editor=Named<LineEdit>(root,"DesignName");editor.Text=text;editor.EmitSignal(LineEdit.SignalName.TextChanged,text);}
    private async Task Pick(Node root,string name,string id){var picker=Named<OptionButton>(root,name);int index=Enumerable.Range(0,picker.ItemCount).Single(i=>picker.GetItemMetadata(i).AsString()==id);picker.Select(index);picker.EmitSignal(OptionButton.SignalName.ItemSelected,(long)index);await Frames(this);}
